import { ApiService } from './apiService';

export class ExportService extends ApiService {

    /**
     * Exports orders to a professionally styled Excel file generated by the backend (Apache POI).
     *
     * The backend endpoint auto-excludes PENDING_PAYMENT and CANCELED orders,
     * groups by product, resolves configurations, and applies branded styling.
     *
     * @param selectedDropIds - Optional drop IDs to filter by. If empty, all drops are included.
     */
    public async exportOrders(selectedDropIds: string[] = []): Promise<void> {
        const params = new URLSearchParams();
        for (const id of selectedDropIds) {
            params.append("dropIds", id);
        }

        const url = `/orders/export${params.toString() ? "?" + params.toString() : ""}`;

        const response = await this.axiosInstance.get(url, {
            responseType: "blob",
        });

        // Extract filename from Content-Disposition header or use default
        let fileName = `fabricacion_${new Date().toISOString().split("T")[0]}.xlsx`;
        const contentDisposition = response.headers["content-disposition"];
        if (contentDisposition) {
            const match = contentDisposition.match(/filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/);
            if (match?.[1]) {
                fileName = match[1].replace(/['"]/g, "");
            }
        }

        // Trigger browser download
        const blob = new Blob([response.data], {
            type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        });
        const downloadUrl = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = downloadUrl;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(downloadUrl);
    }
}

export const exportService = new ExportService();
